	if a, err := netip.ParseAddr(host); err == nil {
		return []netip.Addr{a}, nil
	}
	ips, err := s.resolver.LookupIPAddr(ctx, host)
	if err != nil {
		return nil, err
	}
	addrs := make([]netip.Addr, 0, len(ips))
	for _, ip := range ips {
		a, _ := netip.AddrFromSlice(ip.IP)
		addrs = append(addrs, a)
	}
	return addrs, nil
}

// CheckURL checks a webhook URL before it is saved: an absolute https URL with no user name or password, whose host resolves
// to public addresses only.
func (s *Service) CheckURL(ctx context.Context, raw string) error {
	u, err := url.Parse(raw)
	if err != nil || u.Scheme != "https" || u.Hostname() == "" || u.User != nil {
		return fmt.Errorf("%w: use an absolute https URL without a user name or password", ErrInvalidURL)
	}
	host := u.Hostname()
	addrs, err := s.hostAddrs(ctx, host)
	if err != nil || len(addrs) == 0 {
		return fmt.Errorf("%w: the host %q does not resolve", ErrInvalidURL, host)
	}
	if !slices.ContainsFunc(addrs, func(a netip.Addr) bool { return !isPublic(a) }) {
		return nil
	}
	return fmt.Errorf("%w: the host %q resolves to an address that is not public", ErrInvalidURL, host)
}

// checkDeliveryHost fails unless the host of an endpoint's URL resolves to public addresses only. It runs before every
// delivery, because DNS answers can change after the endpoint was saved.
func (s *Service) checkDeliveryHost(ctx context.Context, raw string) error {
	u, err := url.Parse(raw)
	if err != nil {
		return fmt.Errorf("the endpoint's URL does not parse: %w", err)
	}
	addrs, err := s.hostAddrs(ctx, u.Hostname())
	if err != nil {
		return fmt.Errorf("the endpoint's host does not resolve: %w", err)
	}
	if len(addrs) == 0 {
		return errors.New("the endpoint's host does not resolve")
	}
	if slices.ContainsFunc(addrs, func(a netip.Addr) bool { return !isPublic(a) }) {
		return errors.New("the endpoint's address is not public")
	}
	return nil
}

